Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest...DrcInsertDuplicatePerson")

	Set ihcMrn=pRequest.mrnNum
	Set jsonStreamObject = pRequest.strContainer
	Set msgType=pRequest.duplicateId

	Set tStream = ""
	Set tStream = ##class(%Stream.GlobalCharacter).%New()
	Do tStream.Write(jsonStreamObject.StringValue)		
	Set tStr = tStream.Read()
	$$$TRACE("JSON Request: ")
	if ($L(tStr)>1200){
		  $$$TRACE($E(tStr,1,1200))
		  $$$TRACE($E(tStr,1201,$L(tStr)))
	}else{
	      $$$TRACE(tStr)
	}
	Do tStream.Rewind()

	set URL = ..Adapter.URL

	$$$TRACE("Location: "_URL)

	Set httprequest=##class(%Net.HttpRequest).%New()
	Set httprequest.ContentType="application/json"
	Set httprequest.Https="1"
	Set httprequest.SSLConfiguration = ..Adapter.SSLConfig

	$$$TRACE("Resp Timeout: "_httprequest.Timeout)	

	Do httprequest.EntityBody.Write() ;
	do httprequest.EntityBody.CopyFrom(tStream)
	Set pResponse=##class(Ens.StringResponse).%New()

	try	{

		$$$TRACE("Calling Insert duplicate/duplicateperson identity Service.....")

		set postStatus = httprequest.Post(URL)		
		set postStatusTxt = $SYSTEM.Status.GetOneErrorText(postStatus)
		$$$TRACE("postStatusTxt-->  "_postStatusTxt)
		set response=httprequest.HttpResponse        
       	$$$TRACE("StatusLine: "_response.StatusLine) 
       	set statusLine = response.StatusLine 
       	set statusCode = ""
       	set statusDesc = ""
       	if (statusLine'=""){
			set statusCode=$piece(statusLine," ",2)
			set statusDesc=$piece(statusLine," ",3)			
      	}      
      	$$$TRACE("StatusCode: "_statusCode)  	     
      	$$$TRACE("StatusDesc: "_statusDesc)  

		if (postStatus =1){
	    	$$$TRACE(" DRC Insert service..Duplicate person status 1")   
	    	set len = httprequest.HttpResponse.ContentLength     
    		set respData = httprequest.HttpResponse.Data.Read()
    		$$$TRACE("RESP DATA ???? "_respData)  
		} 
    		set statusInsertDupPerson = ""
    	set consumedJSONobj = ##class(%DynamicAbstractObject).%FromJSON(respData)
        	set statusVal = ((consumedJSONobj.%Get("response")).%Get("service-status")).%Get("status")  
        	$$$TRACE("  statusVal: "_statusVal)     
      		if (statusVal="SUCCESS"){

    			set statusDetailsArr = ((consumedJSONobj.%Get("response")).%Get("status-details"))  
    			$$$TRACE("  statusDetailsArr: "_statusDetailsArr)  		
    		 	// Loop through a JSON Array
  				Set arrObj = statusDetailsArr.%GetIterator()

  				while arrObj.%GetNext(.key, .value) {	  			
	  			  //Set arrElemObj = value.%GetIterator()	 
	  			  //while arrElemObj.%GetNext(.key, .value) {
		  			  $$$TRACE("  key: "_key_" Value: "_value)
		  			  if (key = "STATUS"){
		  			  	Set statusInsertDupPerson = value 
		  			  }		  			  	  			     
	  			  //}	   			 
	   	   		}
    		}
    		Set pResponse.StringValue = statusInsertDupPerson

	}catch e{
		 set errTxt = $System.Status.GetErrorText("Unknown Exception while calling  Cerner Drc duplicate person call  "_e)
 		 $$$TRACE(" Unknown Exception: " _ errTxt)		 
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cern-Demogr-Json-INSERTDUPLICATEPERSON",errTxt)	  		 		  		 		 
	}


	quit tSC
